          RAISE EXCEPTION 'Unauthorized: Clients cannot modify subscriptions directly';
        END IF;
        RETURN NEW;
      END;
      $function$

CREATE OR REPLACE FUNCTION public.check_rate_limit_calls()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
        DECLARE
          recent_count int;
          current_uid uuid := auth.uid();
        BEGIN
          -- Allow backend operations (service_role) to bypass
          IF current_uid IS NULL THEN
            RETURN NEW;
          END IF;

          -- Enforce auth.uid() matching the NEW row to prevent client bypass
          IF NEW.caller_id != current_uid THEN
             RAISE EXCEPTION 'UNAUTHORIZED: caller_id must match auth.uid()';
          END IF;

          -- Count recent actions
          SELECT count(*) INTO recent_count 
          FROM public.calls 
          WHERE caller_id = current_uid 
          AND started_at > now() - interval '1 minute';

          IF recent_count >= 5 THEN
            RAISE EXCEPTION 'RATE_LIMIT_EXCEEDED: calls';
          END IF;

          RETURN NEW;
        END;
        $function$

